content:
:root {
  --bg-primary: #0f172a;
  --bg-card: #1e293b;
  --bg-display: #090d16;
  --bg-history-item: rgba(255, 255, 255, 0.03);
  --bg-history-item-hover: rgba(255, 255, 255, 0.08);

  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-subtle: #64748b;
  --text-display: #ffffff;
  --text-history: #94a3b8;

  --color-primary: #38bdf8;
  --color-operator-hover: #d97706;
  --color-action-hover: #475569;
  --color-equal: #10b981;
  --color-equal-hover: #059669;

  --btn-num-bg: #334155;
  --btn-num-hover: #475569;
  --btn-num-active: #1e293b;
  --btn-action-bg: #475569;
  --btn-operator-bg: #d97706;

  --border-subtle: rgba(255, 255, 255, 0.08);
  --border-focus: #38bdf8;

  --shadow-card: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);
  --shadow-btn: 0 4px 6px -1px rgba(0, 0, 0, 0.3), 0 2px 4px -2px rgba(0, 0, 0, 0.3);
  --shadow-btn-active: 0 1px 2px 0 rgba(0, 0, 0, 0.4);

  --radius-lg: 24px;
  --radius-md: 16px;
  --radius-sm: 10px;
  --radius-btn: 14px;

  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: "SF Mono", "Roboto Mono", Menlo, Consolas, Monaco, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-primary);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  user-select: none;
  -webkit-font-smoothing: antialiased;
}

/* アプリケーション全体 */
.calculator-app {
  width: 100%;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 1.5rem 1rem;
  background: radial-gradient(circle at top center, #1e293b 0%, #0f172a 100%);
}

.calculator-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.25rem;
  width: 100%;
  max-width: 820px;
}

@media (min-width: 768px) {
  .calculator-wrapper {
    flex-direction: row;
    align-items: flex-start;
    justify-content: center;
    gap: 2rem;
  }
}

/* 電卓カード本体 */
.calculator-card {
  width: 100%;
  max-width: 380px;
  background-color: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  position: relative;
}

.calculator-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 0.25rem;
}

.calculator-title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: 0.05em;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* ディスプレイ部 */
.display-container {
  min-width: 0;
  width: 100%;
  background-color: var(--bg-display);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 1.25rem 1.25rem 1rem;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: space-between;
  min-height: 110px;
  word-break: break-all;
  overflow: hidden;
  box-shadow: inset 0 2px 8px rgba(0, 0, 0, 0.6);
}

.display-history {
  font-family: var(--font-mono);
  font-size: 1rem;
  color: var(--text-history);
  min-height: 1.5rem;
  text-align: right;
  width: 100%;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.display-current {
  font-family: var(--font-mono);
  color: var(--text-display);
  font-weight: 600;
  text-align: right;
  width: 100%;
  min-width: 0;
  line-height: 1.2;
  transition: font-size 0.15s ease-out;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  word-break: break-all;
  overflow-wrap: break-word;
}

/* キーパッド */
.keypad-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.75rem;
}

.btn-calc {
  height: 64px;
  border-radius: var(--radius-btn);
  border: none;
  font-family: var(--font-mono);
  font-size: 1.5rem;
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-btn);
  transition: all 0.15s ease-in-out;
  outline: none;
}

.btn-calc:active {
  transform: scale(0.96);
  box-shadow: var(--shadow-btn-active);
}

.btn-calc:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

/* 数字ボタン */
.btn-number {
  background-color: var(--btn-num-bg);
  color: var(--text-main);
}

.btn-number:hover {
  background-color: var(--btn-num-hover);
}

.btn-number:active {
  background-color: var(--btn-num-active);
}

/* 0ボタン */
.btn-zero {
  grid-column: span 2;
  border-radius: var(--radius-btn);
}

/* ファンクション・アクションボタン (C, AC, +/-, %) */
.btn-action {
  background-color: var(--btn-action-bg);
  color: var(--text-main);
  font-size: 1.25rem;
}

.btn-action:hover {
  background-color: var(--color-action-hover);
}

/* 演算子ボタン (+, -, ×, ÷) */
.btn-operator {
  background-color: var(--btn-operator-bg);
  color: #ffffff;
  font-size: 1.625rem;
}

.btn-operator:hover {
  background-color: var(--color-operator-hover);
}

/* 選択中演算子ハイライト */
.btn-operator-active {
  background-color: #ffffff !important;
  color: var(--btn-operator-bg) !important;
  box-shadow: 0 0 12px rgba(245, 158, 11, 0.8);
}

/* イコールボタン */
.btn-equal {
  background-color: var(--color-equal);
  color: #ffffff;
  font-size: 1.75rem;
}

.btn-equal:hover {
  background-color: var(--color-equal-hover);
}

/* 計算履歴セクション */
.history-section {
  width: 100%;
  max-width: 380px;
  background-color: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  gap: 1rem;
  min-height: 480px;
  height: 520px;
}

.history-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-subtle);
  padding-bottom: 0.75rem;
}

.history-title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.history-clear-btn {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 0.875rem;
  cursor: pointer;
  padding: 0.35rem 0.65rem;
  border-radius: var(--radius-sm);
  transition: all 0.2s ease;
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.history-clear-btn:hover {
  color: #f87171;
  background-color: rgba(239, 68, 68, 0.1);
}

.history-clear-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.history-list {
  list-style: none;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding-right: 0.25rem;
  flex: 1;
}

.history-list::-webkit-scrollbar {
  width: 6px;
}

.history-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 4px;
}

.history-item {
  background-color: var(--bg-history-item);
  border: 1px solid rgba(255, 255, 255, 0.04);
  border-radius: var(--radius-sm);
  padding: 0.75rem 1rem;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.25rem;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.15s ease;
  outline: none;
}

.history-item:hover {
  background-color: var(--bg-history-item-hover);
  transform: translateX(-2px);
}

.history-item:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.history-item-formula {
  font-family: var(--font-mono);
  font-size: 0.875rem;
  color: var(--text-muted);
  word-break: break-all;
}

.history-item-result {
  font-family: var(--font-mono);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-primary);
  word-break: break-all;
}

.history-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  flex: 1;
  color: var(--text-subtle);
  font-size: 0.925rem;
  gap: 0.5rem;
  text-align: center;
}

/* 操作説明フッターテキスト */
.instruction-text {
  font-size: 0.8125rem;
  color: var(--text-subtle);
  text-align: center;
  margin-top: 0.5rem;
  line-height: 1.5;
  width: 100%;
  max-width: 420px;
}

/* レスポンシブ調整 */
@media (max-width: 480px) {
  .calculator-card,
  .history-section {
    max-width: 100%;
    padding: 1.25rem;
  }

  .btn-calc {
    height: 56px;
    font-size: 1.35rem;
  }

  .btn-operator,
  .btn-equal {
    font-size: 1.5rem;
  }

  .history-section {
    height: 380px;
    min-height: 340px;
  }
}

/**
 * 電卓で利用可能な四則演算子、または未選択状態を表す型
 */
export type CalculatorOperator = '+' | '-' | '×' | '÷' | null;

/**
 * 計算履歴の1レコードを表すデータ構造
 */
export interface CalcHistoryItem {
  /** 一意な識別子（ミリ秒タイムスタンプ文字列など一意なID） */
  id: string;
  /** 計算式文字列（例: "125 × 8"） */
  formula: string;
  /** 計算結果文字列（例: "1000"） */
  result: string;
}

/**
 * 電卓ディスプレイコンポーネントのProps
 */
export interface DisplayProps {
  /** ディスプレイ上部に表示する直前の計算式 */
  historyFormula: string;
  /** ディスプレイメイン領域に表示する現在の入力値または計算結果 */
  displayValue: string;
}

/**
 * 電卓キーパッドコンポーネントのProps
 */
export interface KeypadProps {
  /** 数字キー（0-9）入力時のコールバック */
  onDigit: (digit: string) => void;
  /** 小数点（.）入力時のコールバック */
  onDecimal: () => void;
  /** 四則演算子（+, -, ×, ÷）選択時のコールバック */
  onOperator: (op: '+' | '-' | '×' | '÷') => void;
  /** 計算実行（=）時のコールバック */
  onEqual: () => void;
  /** 現在の入力値クリアハンドラ（C機能・キーボード操作等の拡張用オプショナルハンドラ） */
  onClear?: () => void;
  /** 全ての状態を初期化するオールクリア（AC）のコールバック */
  onAllClear: () => void;
  /** 正負符号反転（±）のコールバック */
  onToggleSign: () => void;
  /** パーセント（%）計算のコールバック */
  onPercent: () => void;
  /** 現在選択・待機中の演算子（キーのアクティブハイライト用） */
  activeOperator: CalculatorOperator;
}

import { DisplayProps } from '../types';

export default function Display({ historyFormula, displayValue }: DisplayProps) {
  // 桁数および表記（指数表記・小数・エラーなど）に応じた文字サイズ動的調整
  const getFontSize = (text: string): string => {
    if (text.includes('e') || text.includes('エラー')) {
      return text.length > 12 ? '1.5rem' : '1.75rem';
    }

    const len = text.length;
    if (len > 16) return '1.5rem';
    if (len > 12) return '1.875rem';
    if (len > 9) return '2.25rem';
    return '2.75rem';
  };

  return (
    <div className="display-container">
      <div className="display-history" title={historyFormula}>
        {historyFormula || '\u00A0'}
      </div>
      <div
        className="display-current"
        style={{ fontSize: getFontSize(displayValue) }}
        title={displayValue}
        role="status"
        aria-live="polite"
      >
        {displayValue}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { KeypadProps } from '../types';

export default function Keypad({
  onDigit,
  onDecimal,
  onOperator,
  onEqual,
  onClear,
  onAllClear,
  onToggleSign,
  onPercent,
  activeOperator,
}: KeypadProps) {
  const [hasInput, setHasInput] = useState<boolean>(false);

  const handleDigit = (digit: string) => {
    setHasInput(true);
    onDigit(digit);
  };

  const handleDecimal = () => {
    setHasInput(true);
    onDecimal();
  };

  const handleClearOrAllClear = () => {
    if (hasInput) {
      onClear();
      setHasInput(false);
    } else {
      onAllClear();
    }
  };

  const handleOperator = (op: '+' | '-' | '×' | '÷') => {
    setHasInput(false);
    onOperator(op);
  };

  const handleEqual = () => {
    setHasInput(false);
    onEqual();
  };

  const getOperatorClass = (op: '+' | '-' | '×' | '÷') => {
    return activeOperator === op
      ? 'btn-calc btn-operator btn-operator-active'
      : 'btn-calc btn-operator';
  };

  return (
    <div className="keypad-grid">
      {/* 1行目: オールクリア/クリア、符号反転、パーセント、除算 */}
      <button
        type="button"
        className="btn-calc btn-action"
        onClick={handleClearOrAllClear}
        aria-label={hasInput ? '入力クリア' : 'オールクリア'}
      >
        {hasInput ? 'C' : 'AC'}
      </button>
      <button
        type="button"
        className="btn-calc btn-action"
        onClick={onToggleSign}
        aria-label="正負切り替え"
      >
        ±
      </button>
      <button
        type="button"
        className="btn-calc btn-action"
        onClick={onPercent}
        aria-label="パーセント"
      >
        %
      </button>
      <button
        type="button"
        className={getOperatorClass('÷')}
        onClick={() => handleOperator('÷')}
        aria-label="除算"
      >
        ÷
      </button>

      {/* 2行目: 7, 8, 9, 乗算 */}
      <button
        type="button"
        className="btn-calc btn-number"
        onClick={() => handleDigit('7')}
        aria-label="数字の7"
      >
        7
      </button>
      <button
        type="button"
        className="btn-calc btn-number"
        onClick={() => handleDigit('8')}
        aria-label="数字の8"
      >
        8
      </button>
      <button
        type="button"
        className="btn-calc btn-number"
        onClick={() => handleDigit('9')}
        aria-label="数字の9"
      >
        9
      </button>
      <button
        type="button"
        className={getOperatorClass('×')}
        onClick={() => handleOperator('×')}
        aria-label="乗算"
      >
        ×
      </button>

      {/* 3行目: 4, 5, 6, 減算 */}
      <button
        type="button"
        className="btn-calc btn-number"
        onClick={() => handleDigit('4')}
        aria-label="数字の4"
      >
        4
      </button>
      <button
        type="button"
        className="btn-calc btn-number"
        onClick={() => handleDigit('5')}
        aria-label="数字の5"
      >
        5
      </button>
      <button
        type="button"
        className="btn-calc btn-number"
        onClick={() => handleDigit('6')}
        aria-label="数字の6"
      >
        6
      </button>
      <button
        type="button"
        className={getOperatorClass('-')}
        onClick={() => handleOperator('-')}
        aria-label="減算"
      >
        -
      </button>

      {/* 4行目: 1, 2, 3, 加算 */}
      <button
        type="button"
        className="btn-calc btn-number"
        onClick={() => handleDigit('1')}
        aria-label="数字の1"
      >
        1
      </button>
      <button
        type="button"
        className="btn-calc btn-number"
        onClick={() => handleDigit('2')}
        aria-label="数字の2"
      >
        2
      </button>
      <button
        type="button"
        className="btn-calc btn-number"
        onClick={() => handleDigit('3')}
        aria-label="数字の3"
      >
        3
      </button>
      <button
        type="button"
        className={getOperatorClass('+')}
        onClick={() => handleOperator('+')}
        aria-label="加算"
      >
        +
      </button>

      {/* 5行目: 0 (横幅2マス), 小数点, イコール */}
      <button
        type="button"
        className="btn-calc btn-number btn-zero"
        onClick={() => handleDigit('0')}
        aria-label="数字の0"
      >
        0
      </button>
      <button
        type="button"
        className="btn-calc btn-number"
        onClick={handleDecimal}
        aria-label="小数点"
      >
        .
      </button>
      <button
        type="button"
        className="btn-calc btn-equal"
        onClick={handleEqual}
        aria-label="計算実行"
      >
        =
      </button>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { CalculatorOperator, CalcHistoryItem } from './types';
import Display from './components/Display';
import Keypad from './components/Keypad';

export default function App() {
  const [displayValue, setDisplayValue] = useState<string>('0');
  const [previousValue, setPreviousValue] = useState<number | null>(null);
  const [operator, setOperator] = useState<CalculatorOperator>(null);
  const [waitingForOperand, setWaitingForOperand] = useState<boolean>(false);
  const [historyFormula, setHistoryFormula] = useState<string>('');
  const [history, setHistory] = useState<CalcHistoryItem[]>([
    { id: 'sample-1', formula: '125 × 8', result: '1000' },
    { id: 'sample-2', formula: '1000 ÷ 4', result: '250' },
  ]);

  // 数値フォーマット処理（計算精度の丸め）
  const formatResult = (num: number): string => {
    if (isNaN(num)) return 'エラー';
    if (!isFinite(num)) return 'エラー (0除算)';
    const rounded = Number(Math.round(Number(num + 'e+10')) + 'e-10');
    const str = String(rounded);
    if (str.length > 14) {
      return rounded.toExponential(6);
    }
    return str;
  };

  // 数字キー入力
  const handleDigit = useCallback((digit: string) => {
    if (displayValue === 'エラー' || displayValue === 'エラー (0除算)') {
      setDisplayValue(digit);
      setWaitingForOperand(false);
      setOperator(null);
      setPreviousValue(null);
      setHistoryFormula('');
      return;
    }

    if (waitingForOperand) {
      setDisplayValue(digit);
      setWaitingForOperand(false);
    } else {
      if (displayValue === '0') {
        setDisplayValue(digit);
      } else {
        if (displayValue.replace(/[-.]/g, '').length < 15) {
          setDisplayValue(displayValue + digit);
        }
      }
    }
  }, [displayValue, waitingForOperand]);

  // 小数点入力
  const handleDecimal = useCallback(() => {
    if (displayValue === 'エラー' || displayValue === 'エラー (0除算)') {
      setDisplayValue('0.');
      setWaitingForOperand(false);
      setOperator(null);
      setPreviousValue(null);
      setHistoryFormula('');
      return;
    }

    if (waitingForOperand) {
      setDisplayValue('0.');
      setWaitingForOperand(false);
      return;
    }

    if (!displayValue.includes('.')) {
      setDisplayValue(displayValue + '.');
    }
  }, [displayValue, waitingForOperand]);

  // 計算実行ヘルパー
  const calculate = (first: number, second: number, op: '+' | '-' | '×' | '÷'): number => {
    switch (op) {
      case '+':
        return first + second;
      case '-':
        return first - second;
      case '×':
        return first * second;
      case '÷':
        return second === 0 ? NaN : first / second;
      default:
        return second;
    }
  };

  // 演算子キー入力
  const handleOperator = useCallback((nextOperator: '+' | '-' | '×' | '÷') => {
    const inputValue = parseFloat(displayValue);

    if (displayValue === 'エラー' || displayValue === 'エラー (0除算)') {
      return;
    }

    if (previousValue === null) {
      setPreviousValue(inputValue);
      setHistoryFormula(`${displayValue} ${nextOperator}`);
    } else if (operator) {
      if (!waitingForOperand) {
        const result = calculate(previousValue, inputValue, operator);
        const resultString = formatResult(result);
        setDisplayValue(resultString);
        setPreviousValue(result);
        setHistoryFormula(`${resultString} ${nextOperator}`);
      } else {
        setHistoryFormula(`${previousValue} ${nextOperator}`);
      }
    }

    setWaitingForOperand(true);
    setOperator(nextOperator);
  }, [displayValue, previousValue, operator, waitingForOperand]);

  // ユニークID生成ヘルパー
  const generateId = (): string => {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
      return crypto.randomUUID();
    }
    return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
  };

  // イコール押下
  const handleEqual = useCallback(() => {
    if (operator === null || previousValue === null) {
      return;
    }

    const inputValue = parseFloat(displayValue);
    const formulaStr = `${previousValue} ${operator} ${displayValue}`;
    const result = calculate(previousValue, inputValue, operator);
    const resultString = formatResult(result);

    setHistoryFormula(`${formulaStr} =`);
    setDisplayValue(resultString);
    setPreviousValue(null);
    setOperator(null);
    setWaitingForOperand(true);

    if (resultString !== 'エラー' && resultString !== 'エラー (0除算)') {
      const newItem: CalcHistoryItem = {
        id: generateId(),
        formula: formulaStr,
        result: resultString,
      };
      setHistory((prev) => [newItem, ...prev.slice(0, 49)]);
    }
  }, [operator, previousValue, displayValue]);

  // クリア（現在の入力のみリセット）
  const handleClear = useCallback(() => {
    setDisplayValue('0');
  }, []);

  // オールクリア
  const handleAllClear = useCallback(() => {
    setDisplayValue('0');
    setPreviousValue(null);
    setOperator(null);
    setWaitingForOperand(false);
    setHistoryFormula('');
  }, []);

  // 符号反転
  const handleToggleSign = useCallback(() => {
    if (displayValue === '0' || displayValue === 'エラー' || displayValue === 'エラー (0除算)') return;
    if (displayValue.startsWith('-')) {
      setDisplayValue(displayValue.substring(1));
    } else {
      setDisplayValue('-' + displayValue);
    }
  }, [displayValue]);

  // パーセント
  const handlePercent = useCallback(() => {
    if (displayValue === 'エラー' || displayValue === 'エラー (0除算)') return;
    const current = parseFloat(displayValue);
    if (isNaN(current)) return;
    const result = current / 100;
    setDisplayValue(formatResult(result));
  }, [displayValue]);

  // 履歴からの呼び出し
  const handleSelectHistoryItem = (item: CalcHistoryItem) => {
    setDisplayValue(item.result);
    setPreviousValue(null);
    setOperator(null);
    setWaitingForOperand(true);
    setHistoryFormula(item.formula + ' =');
  };

  // 履歴クリア
  const handleClearHistory = () => {
    setHistory([]);
  };

  // キーボードイベントハンドリング
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) {
        return;
      }

      if (e.key >= '0' && e.key <= '9') {
        e.preventDefault();
        handleDigit(e.key);
      } else if (e.key === '.') {
        e.preventDefault();
        handleDecimal();
      } else if (e.key === '+') {
        e.preventDefault();
        handleOperator('+');
      } else if (e.key === '-') {
        e.preventDefault();
        handleOperator('-');
      } else if (e.key === '*') {
        e.preventDefault();
        handleOperator('×');
      } else if (e.key === '/') {
        e.preventDefault();
        handleOperator('÷');
      } else if (e.key === 'Enter' || e.key === '=') {
        e.preventDefault();
        handleEqual();
      } else if (e.key === 'Escape') {
        e.preventDefault();
        handleAllClear();
      } else if (e.key === 'Backspace') {
        e.preventDefault();
        if (displayValue === 'エラー' || displayValue === 'エラー (0除算)') {
          setDisplayValue('0');
        } else if (displayValue.length > 1) {
          // マイナス1桁の場合や「-0.」等の制御
          const next = displayValue.slice(0, -1);
          setDisplayValue(next === '-' || next === '' ? '0' : next);
        } else {
          setDisplayValue('0');
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [displayValue, handleDigit, handleDecimal, handleOperator, handleEqual, handleAllClear]);

  return (
    <div className="calculator-app">
      <div className="calculator-wrapper">
        {/* 電卓本体カード */}
        <main className="calculator-card" aria-label="高機能電卓">
          <header className="calculator-header">
            <h1 className="calculator-title">
              <span>🧮</span>
              <span>高機能電卓</span>
            </h1>
          </header>

          <Display historyFormula={historyFormula} displayValue={displayValue} />

          <Keypad
            onDigit={handleDigit}
            onDecimal={handleDecimal}
            onOperator={handleOperator}
            onEqual={handleEqual}
            onClear={handleClear}
            onAllClear={handleAllClear}
            onToggleSign={handleToggleSign}
            onPercent={handlePercent}
            activeOperator={operator}
          />
        </main>

        {/* 計算履歴セクション */}
        <aside className="history-section" aria-label="計算履歴一覧">
          <header className="history-header">
            <h2 className="history-title">
              <span>🕒</span>
              <span>計算履歴</span>
            </h2>
            {history.length > 0 && (
              <button
                type="button"
                className="history-clear-btn"
                onClick={handleClearHistory}
                aria-label="履歴を全消去"
              >
                <span>🗑️</span>
                <span>全消去</span>
              </button>
            )}
          </header>

          {history.length === 0 ? (
            <div className="history-empty">
              <span>📝</span>
              <p>計算履歴がありません</p>
            </div>
          ) : (
            <ul className="history-list">
              {history.map((item) => (
                <li
                  key={item.id}
                  className="history-item"
                  role="button"
                  tabIndex={0}
                  onClick={() => handleSelectHistoryItem(item)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      handleSelectHistoryItem(item);
                    }
                  }}
                  title="クリックまたはEnterキーで結果を入力"
                  aria-label={`${item.formula} = ${item.result}。押すと結果を入力値として復元します`}
                >
                  <span className="history-item-formula">{item.formula} =</span>
                  <span className="history-item-result">{item.result}</span>
                </li>
              ))}
            </ul>
          )}
        </aside>
      </div>

      <footer className="instruction-text">
        キーボード入力対応: 数字キー (0-9), 四則演算 (+, -, *, /), 決定 (Enter/=), オールクリア (Esc), 1文字削除 (Backspace)
      </footer>
    </div>
  );
}
